'use client';

import { PieChart, Pie, Cell, ResponsiveContainer, Legend, Tooltip } from 'recharts';
import { ChartContainer, ChartTooltip, ChartTooltipContent } from '@/components/ui/chart';

interface ProjectStatsChartProps {
  data: { status: string; count: number; percentage: number }[];
  total?: number;
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444']; // blue, green, orange, red

export function ProjectStatsChart({ data, total }: ProjectStatsChartProps) {
  const chartData = data.map((item, index) => ({
    ...item,
    fill: COLORS[index % COLORS.length],
  }));

  return (
    <div className="w-full">
      {total && (
        <div className="text-center mb-2">
          <p className="text-lg font-semibold">Total projects: {total.toLocaleString()}</p>
        </div>
      )}
      <ChartContainer config={{}} className="h-[300px] w-full">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={chartData}
              cx="50%"
              cy="50%"
              labelLine={false}
              outerRadius={80}
              innerRadius={40}
              fill="#8884d8"
              dataKey="count"
            >
              {chartData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.fill} />
              ))}
            </Pie>
            <ChartTooltip content={<ChartTooltipContent />} />
            <Legend
              formatter={(value) => {
                const item = chartData.find((d) => d.status === value);
                return item ? `${item.status} (${item.percentage}%)` : value;
              }}
              iconType="circle"
            />
          </PieChart>
        </ResponsiveContainer>
      </ChartContainer>
    </div>
  );
}