'use client';

import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { ChartContainer, ChartTooltip, ChartTooltipContent } from '@/components/ui/chart';

interface NewUsersChartProps {
  data: { month: string; provider: number; client: number }[];
}

const chartConfig = {
  provider: {
    label: 'Provider',
    color: '#fbbf24', // yellow
  },
  client: {
    label: 'Client',
    color: '#ef4444', // red
  },
};

export function NewUsersChart({ data }: NewUsersChartProps) {
  return (
    <ChartContainer config={chartConfig} className="h-[300px] w-full">
      <ResponsiveContainer width="100%" height="100%">
        <LineChart data={data} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
          <XAxis
            dataKey="month"
            tick={{ fill: 'hsl(var(--muted-foreground))' }}
            stroke="hsl(var(--border))"
          />
          <YAxis
            tick={{ fill: 'hsl(var(--muted-foreground))' }}
            stroke="hsl(var(--border))"
            tickFormatter={(value) => `${(value / 1000).toFixed(0)}k`}
          />
          <ChartTooltip content={<ChartTooltipContent />} />
          <Legend
            wrapperStyle={{ paddingTop: '20px' }}
            iconType="square"
            formatter={(value) => chartConfig[value as keyof typeof chartConfig]?.label || value}
          />
          <Line
            type="monotone"
            dataKey="provider"
            stroke={chartConfig.provider.color}
            strokeWidth={2}
            dot={{ fill: chartConfig.provider.color, r: 4 }}
            activeDot={{ r: 6 }}
          />
          <Line
            type="monotone"
            dataKey="client"
            stroke={chartConfig.client.color}
            strokeWidth={2}
            dot={{ fill: chartConfig.client.color, r: 4 }}
            activeDot={{ r: 6 }}
          />
        </LineChart>
      </ResponsiveContainer>
    </ChartContainer>
  );
}